PRAGMA foreign_keys = ON;

CREATE TABLE IF NOT EXISTS customers (id INTEGER PRIMARY KEY, name TEXT NOT NULL, phone TEXT, address TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS vehicles (id INTEGER PRIMARY KEY, customer_id INTEGER REFERENCES customers(id), plate TEXT NOT NULL, brand TEXT, model TEXT, color TEXT, mileage INTEGER DEFAULT 0, last_service TEXT, service_interval INTEGER DEFAULT 5000, photo_path TEXT);
CREATE TABLE IF NOT EXISTS mechanics (id INTEGER PRIMARY KEY, name TEXT NOT NULL, phone TEXT, active INTEGER DEFAULT 1);
CREATE TABLE IF NOT EXISTS products (id INTEGER PRIMARY KEY, code TEXT UNIQUE, name TEXT NOT NULL, stock REAL DEFAULT 0, buy_price REAL DEFAULT 0, sale_price REAL DEFAULT 0, min_stock REAL DEFAULT 0, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS suppliers (id INTEGER PRIMARY KEY, name TEXT NOT NULL, phone TEXT, address TEXT);
CREATE TABLE IF NOT EXISTS work_orders (id INTEGER PRIMARY KEY, code TEXT UNIQUE NOT NULL, customer_id INTEGER REFERENCES customers(id), vehicle_id INTEGER REFERENCES vehicles(id), mechanic_id INTEGER REFERENCES mechanics(id), mileage INTEGER, complaint TEXT, status TEXT CHECK(status IN ('pending','in_progress','ready','delivered')) DEFAULT 'pending', labor_amount REAL DEFAULT 0, discount REAL DEFAULT 0, paid_amount REAL DEFAULT 0, created_at TEXT DEFAULT CURRENT_TIMESTAMP, delivered_at TEXT);
CREATE TABLE IF NOT EXISTS work_order_items (id INTEGER PRIMARY KEY, work_order_id INTEGER REFERENCES work_orders(id) ON DELETE CASCADE, product_id INTEGER REFERENCES products(id), description TEXT, quantity REAL DEFAULT 1, unit_price REAL DEFAULT 0);
CREATE TABLE IF NOT EXISTS work_order_photos (id INTEGER PRIMARY KEY, work_order_id INTEGER REFERENCES work_orders(id) ON DELETE CASCADE, path TEXT NOT NULL, caption TEXT);
CREATE TABLE IF NOT EXISTS purchases (id INTEGER PRIMARY KEY, code TEXT UNIQUE NOT NULL, supplier_id INTEGER REFERENCES suppliers(id), total REAL DEFAULT 0, paid_amount REAL DEFAULT 0, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS purchase_items (id INTEGER PRIMARY KEY, purchase_id INTEGER REFERENCES purchases(id) ON DELETE CASCADE, product_id INTEGER REFERENCES products(id), quantity REAL NOT NULL, unit_price REAL NOT NULL);
CREATE TABLE IF NOT EXISTS sales (id INTEGER PRIMARY KEY, code TEXT UNIQUE NOT NULL, customer_id INTEGER REFERENCES customers(id), total REAL DEFAULT 0, discount REAL DEFAULT 0, paid_amount REAL DEFAULT 0, payment_method TEXT DEFAULT 'cash', created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sale_items (id INTEGER PRIMARY KEY, sale_id INTEGER REFERENCES sales(id) ON DELETE CASCADE, product_id INTEGER REFERENCES products(id), quantity REAL NOT NULL, unit_price REAL NOT NULL);
CREATE TABLE IF NOT EXISTS cash_transactions (id INTEGER PRIMARY KEY, type TEXT CHECK(type IN ('receipt','payment')) NOT NULL, amount REAL NOT NULL, description TEXT, reference_type TEXT, reference_id INTEGER, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS bank_accounts (id INTEGER PRIMARY KEY, name TEXT NOT NULL, bank_name TEXT, card_number TEXT, opening_balance REAL DEFAULT 0);
CREATE TABLE IF NOT EXISTS bank_transactions (id INTEGER PRIMARY KEY, account_id INTEGER REFERENCES bank_accounts(id), type TEXT CHECK(type IN ('deposit','withdrawal')) NOT NULL, amount REAL NOT NULL, description TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS checks (id INTEGER PRIMARY KEY, type TEXT CHECK(type IN ('received','paid')) NOT NULL, number TEXT NOT NULL, bank TEXT, amount REAL NOT NULL, due_date TEXT NOT NULL, status TEXT CHECK(status IN ('in_hand','deposited','cashed','bounced','expended')) DEFAULT 'in_hand', person_type TEXT, person_id INTEGER, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS ledger_entries (id INTEGER PRIMARY KEY, person_type TEXT CHECK(person_type IN ('customer','supplier')) NOT NULL, person_id INTEGER NOT NULL, debit REAL DEFAULT 0, credit REAL DEFAULT 0, description TEXT, reference_type TEXT, reference_id INTEGER, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS expenses (id INTEGER PRIMARY KEY, title TEXT NOT NULL, amount REAL NOT NULL, category TEXT, paid_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS app_settings (key TEXT PRIMARY KEY, value TEXT);
